diff --git a/src/filter_core/filter_pck.c b/src/filter_core/filter_pck.c
index b093e8a70..c3595e722 100644
--- a/src/filter_core/filter_pck.c
+++ b/src/filter_core/filter_pck.c
@@ -105,6 +105,21 @@ static GF_FilterPacket *gf_filter_pck_new_alloc_internal(GF_FilterPid *pid, u32
 	GF_FilterPacket *closest=NULL;
 	u32 count, max_reservoir_size;

+	/*
+	 * Defensive programming: some callers may invoke packet allocation while the
+	 * PID is not yet created or already removed (eg. during reconfiguration / end
+	 * of stream). The allocator assumes a valid pid->filter and will dereference
+	 * it very early (PID_IS_INPUT, reservoir access, reset_props).
+	 *
+	 * Return NULL instead of crashing on NULL PID.
+	 */
+	if (data) *data = NULL;
+	if (!pid || !pid->filter) {
+		GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Attempt to allocate a packet on an invalid PID\n"));
+		return NULL;
+	}
+
+
 	if (PID_IS_INPUT(pid)) {
 		GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Attempt to allocate a packet on an input PID in filter %s\n", pid->filter->name));
 		return NULL;

diff --git a/src/class.c b/src/class.c
index ec9c648e5..f28fb2355 100644
--- a/src/class.c
+++ b/src/class.c
@@ -4,6 +4,7 @@
 ** See Copyright Notice in mruby.h
 */

+#include <stdint.h>
 #include <mruby.h>
 #include <mruby/array.h>
 #include <mruby/hash.h>
@@ -357,6 +358,17 @@ prepare_singleton_class(mrb_state *mrb, struct RBasic *o)
 {
   struct RClass *sc, *c;

+  /* Defensive hardening: under memory corruption or crafted bytecode, it is
+     possible to reach here with an invalid object/class pointer (ASan report
+     shows o->c == 0x10). Avoid dereferencing such pointers.
+
+     For normal execution, these branches are never taken. */
+  if (o == NULL) return;
+  if (o->c == NULL || (uintptr_t)o->c < 4096) {
+    o->c = mrb->object_class;
+  }
+
+
   if (o->c->tt == MRB_TT_SCLASS) return;
   sc = MRB_OBJ_ALLOC(mrb, MRB_TT_SCLASS, mrb->class_class);
   sc->flags |= MRB_FL_CLASS_IS_INHERITED;
@@ -1682,6 +1694,14 @@ mrb_singleton_class_ptr(mrb_state *mrb, mrb_value v)
     break;
   }
   obj = mrb_basic_ptr(v);
+  /* If the mrb_value is corrupted, mrb_basic_ptr() (or the class pointer) may
+     be NULL/near-NULL. Do not propagate this into prepare_singleton_class(). */
+  if (obj == NULL || (uintptr_t)obj < 4096) {
+    return mrb->object_class;
+  }
+  if (obj->c == NULL || (uintptr_t)obj->c < 4096) {
+    obj->c = mrb->object_class;
+  }
   prepare_singleton_class(mrb, obj);
   return obj->c;
 }

