+NJS_EXPORT njs_bool_t
+njs_mp_is_valid(njs_mp_t *mp, void *p, size_t size)
+{
+    njs_mp_block_t  *block;
+    u_char          *start;
+
+    if (njs_slow_path(mp == NULL || p == NULL)) {
+        return 0;
+    }
+
+    start = (u_char *) p;
+    block = njs_mp_find_block(&mp->blocks, start);
+    if (block == NULL) {
+        return 0;
+    }
+
+    return (start + size <= block->start + block->size);
+}
