+/* Grow *dest to ensure there is room for (off + need + 1) bytes.
+   Keeps *d in sync with *dest.
+ */
+static int
+ensure_room (char **dest, char **d, size_t *len, size_t need)
+{
+  size_t off = (size_t)(*d - *dest);
+  if (off + need + 1 <= *len)
+    return 1;
+
+  /* Grow at least enough for the current need, with some slack. */
+  size_t newlen = *len;
+  size_t minlen = off + need + 1;
+  while (newlen < minlen)
+    {
+      /* avoid tiny increments for long strings */
+      size_t inc = (newlen < 1024) ? 64 : (newlen / 2);
+      newlen += inc;
+      if (newlen < *len) /* overflow */
+        return 0;
+    }
+
+  char *tmp = realloc (*dest, newlen);
+  if (!tmp)
+    return 0;
+  *dest = tmp;
+  *d = tmp + off;
+  *len = newlen;
+  return 1;
+}
+
+static int
+append_mem (char **dest, char **d, size_t *len, const char *s, size_t n)
+{
+  if (!ensure_room (dest, d, len, n))
+    return 0;
+  memcpy (*d, s, n);
+  *d += n;
+  **d = '\0';
+  return 1;
+}
